def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))

    merged = [[sorted_intervals[0][0], sorted_intervals[0][1]]]

    for i in range(1, len(sorted_intervals)):
        start, end = sorted_intervals[i]
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

import heapq

def toposort(nodes, edges):
    nodes = list(nodes)
    edge_set = set(edges)

    adj = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in edge_set:
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result

def parse_sse(chunks):
    raw = b''.join(chunks)
    text = raw.decode('utf-8')
    text = text.replace('\r\n', '\n')
    lines = text.split('\n')

    events = []
    current_data = []

    for line in lines:
        if line == '':
            if current_data:
                event_data = '\n'.join(current_data)
                if event_data == '[DONE]':
                    break
                events.append(event_data)
            current_data = []
            continue

        if line.startswith(':'):
            continue

        if ':' in line:
            field, _, value = line.partition(':')
            if value.startswith(' '):
                value = value[1:]
        else:
            field = line
            value = ''

        if field == 'data':
            current_data.append(value)

    return events

import math


def retry_delay(attempt, base, cap):
    """Return min(cap, base * 2**attempt) as a float.

    Handles extremely large attempt values (e.g. 10**9) without
    constructing a giant integer or overflowing.
    """
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("attempt, base, and cap must all be nonnegative")

    # Short-circuit: if either multiplier or ceiling is zero the answer is 0.
    if base == 0 or cap == 0:
        return 0.0

    # attempt == 0 → 2**0 == 1, so result is min(cap, base)
    if attempt == 0:
        return min(float(cap), float(base))

    # For attempt > 1023 the value 2.0**attempt overflows IEEE-754 double.
    # Since base > 0 here, base * 2**attempt is effectively infinite,
    # which is certainly >= cap (a finite number).  Return cap.
    if attempt > 1023:
        return float(cap)

    # Safe path: 2.0 ** attempt is at most 2**1023 ≈ 8.99e307, a finite float.
    # The multiplication base * (2.0**attempt) may still overflow to inf
    # (if base is itself very large), but that simply means the result
    # exceeds the finite cap.
    result = base * (2.0 ** attempt)

    if math.isinf(result) or result >= cap:
        return float(cap)

    return float(result)

def fifo_admit(active, queued, budget, slots):
    for q in queued:
        if q > budget:
            raise ValueError(f"queued reservation {q} exceeds budget {budget}")

    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    admitted = []
    remaining = []

    for i, req in enumerate(queued):
        if remaining_slots > 0 and req <= remaining_budget:
            admitted.append(req)
            remaining_budget -= req
            remaining_slots -= 1
        else:
            remaining = list(queued[i:])
            break

    return (admitted, remaining)
